package erratum

import (
	"errors"
	"fmt"
)

// open calls opener, retrying while it fails with a TransientError.
// It returns the resource on success, or the first non-transient error.
func open(opener ResourceOpener) (Resource, error) {
	for {
		res, err := opener()
		if err == nil {
			return res, nil
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return nil, err
	}
}

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// If Frob panics with a FrobError, the resource's Defrob method is called
// with the FrobError's defrobTag (before the resource is closed), and the
// FrobError is returned. Any other panic is recovered and returned as an
// error.
func Use(opener ResourceOpener, input string) (err error) {
	res, err := open(opener)
	if err != nil {
		return err
	}
	if res == nil {
		return nil
	}
	defer res.Close()

	defer func() {
		if r := recover(); r == nil {
			return
		}
		switch p := r.(type) {
		case FrobError:
			res.Defrob(p.defrobTag)
